import React, { useState, useEffect, useRef } from 'react';
import './App.css';

function App() {
  const [messages, setMessages] = useState([
    { id: 1, type: 'bot', text: 'Hello! I\'m your AI Personal Assistant. I can help you manage reminders, meetings, and keep track of your schedule. What would you like me to do?' }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [reminders, setReminders] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [activeTab, setActiveTab] = useState('chat');
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const API_BASE_URL = 'http://localhost:5000/api';

  const fetchReminders = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/reminders`);
      const data = await response.json();
      setReminders(data);
    } catch (error) {
      console.error('Error fetching reminders:', error);
    }
  };

  const fetchMeetings = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/meetings`);
      const data = await response.json();
      setMeetings(data);
    } catch (error) {
      console.error('Error fetching meetings:', error);
    }
  };

  const fetchNotifications = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/notifications`);
      const data = await response.json();
      setNotifications(data);
    } catch (error) {
      console.error('Error fetching notifications:', error);
    }
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    fetchReminders();
    fetchMeetings();
    fetchNotifications();

    const interval = setInterval(() => {
      fetchNotifications();
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  const handleSendMessage = async (e) => {
    e.preventDefault();

    if (!inputValue.trim()) return;

    const userMessage = {
      id: messages.length + 1,
      type: 'user',
      text: inputValue
    };
    setMessages([...messages, userMessage]);
    setInputValue('');
    setLoading(true);

    try {
      const parseResponse = await fetch(`${API_BASE_URL}/assistant/parse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ input: inputValue })
      });
      const parseData = await parseResponse.json();

      let botMessage = {
        id: messages.length + 2,
        type: 'bot',
        text: parseData.message,
        action: parseData.action
      };

      if (parseData.action === 'show_schedule') {
        await fetchMeetings();
        await fetchReminders();
        botMessage.text = 'Here\'s your upcoming schedule:';
      }

      setMessages(prev => [...prev, botMessage]);

      if (parseData.action === 'reminder') {
        setMessages(prev => [...prev, {
          id: prev.length + 1,
          type: 'system',
          text: 'You can add a reminder using the "Reminders" tab or by saying something like: "Remind me to call John tomorrow at 2 PM"'
        }]);
      } else if (parseData.action === 'meeting') {
        setMessages(prev => [...prev, {
          id: prev.length + 1,
          type: 'system',
          text: 'You can add a meeting using the "Meetings" tab or by saying something like: "Schedule a meeting with Sarah at 3 PM tomorrow"'
        }]);
      }
    } catch (error) {
      setMessages(prev => [...prev, {
        id: prev.length + 1,
        type: 'bot',
        text: 'Sorry, I encountered an error. Please try again.'
      }]);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteReminder = async (id) => {
    try {
      await fetch(`${API_BASE_URL}/reminders/${id}`, { method: 'DELETE' });
      fetchReminders();
    } catch (error) {
      console.error('Error deleting reminder:', error);
    }
  };

  const handleQuickReminder = async () => {
    const title = prompt('What do you want to be reminded about?');
    if (!title) return;

    const timeString = prompt('When? (e.g., "tomorrow at 2 PM", "in 30 minutes")');
    if (!timeString) return;

    const reminderTime = new Date();
    reminderTime.setHours(reminderTime.getHours() + 1);

    try {
      await fetch(`${API_BASE_URL}/reminders`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          description: `Set for: ${timeString}`,
          reminder_time: reminderTime.toISOString(),
          notification_before: 10
        })
      });
      fetchReminders();
      setMessages(prev => [...prev, {
        id: prev.length + 1,
        type: 'bot',
        text: `✅ Reminder set: "${title}" - You'll be notified 10 minutes before.`
      }]);
    } catch (error) {
      console.error('Error creating reminder:', error);
    }
  };

  const handleQuickMeeting = async () => {
    const title = prompt('What is the meeting about?');
    if (!title) return;

    const time = prompt('When? (e.g., "tomorrow at 3 PM")');
    if (!time) return;

    const meetingTime = new Date();
    meetingTime.setHours(meetingTime.getHours() + 2);
    const endTime = new Date(meetingTime);
    endTime.setHours(endTime.getHours() + 1);

    try {
      await fetch(`${API_BASE_URL}/meetings`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title,
          description: `Scheduled for: ${time}`,
          start_time: meetingTime.toISOString(),
          end_time: endTime.toISOString(),
          location: ''
        })
      });
      fetchMeetings();
      setMessages(prev => [...prev, {
        id: prev.length + 1,
        type: 'bot',
        text: `📅 Meeting scheduled: "${title}" - I'll remind you 10 minutes before.`
      }]);
    } catch (error) {
      console.error('Error creating meeting:', error);
    }
  };

  const formatTime = (isoString) => {
    const date = new Date(isoString);
    return date.toLocaleString();
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1>🤖 AI Personal Assistant</h1>
        <p>Your 24/7 Smart Schedule Manager</p>
      </header>

      <div className="tab-navigation">
        <button
          className={`tab-btn ${activeTab === 'chat' ? 'active' : ''}`}
          onClick={() => setActiveTab('chat')}
        >
          💬 Chat
        </button>
        <button
          className={`tab-btn ${activeTab === 'reminders' ? 'active' : ''}`}
          onClick={() => setActiveTab('reminders')}
        >
          ⏰ Reminders ({reminders.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'meetings' ? 'active' : ''}`}
          onClick={() => setActiveTab('meetings')}
        >
          📅 Meetings ({meetings.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'notifications' ? 'active' : ''}`}
          onClick={() => setActiveTab('notifications')}
        >
          🔔 Notifications ({notifications.filter(n => !n.read).length})
        </button>
      </div>

      <div className="tab-content">
        {activeTab === 'chat' && (
          <div className="chat-container">
            <div className="messages-list">
              {messages.map((msg) => (
                <div key={msg.id} className={`message message-${msg.type}`}>
                  <div className="message-content">{msg.text}</div>
                </div>
              ))}
              {loading && (
                <div className="message message-bot">
                  <div className="message-content typing">Thinking...</div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSendMessage} className="chat-input-form">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Tell me what you need... e.g., 'Remind me to call John tomorrow at 2 PM'"
                className="chat-input"
              />
              <button type="submit" className="send-btn" disabled={loading}>
                Send
              </button>
            </form>
          </div>
        )}

        {activeTab === 'reminders' && (
          <div className="reminders-container">
            <button onClick={handleQuickReminder} className="action-btn">
              ➕ Add Reminder
            </button>

            {reminders.length === 0 ? (
              <p className="empty-state">No reminders yet. Create one to get started!</p>
            ) : (
              <div className="items-list">
                {reminders.map((reminder) => (
                  <div key={reminder.id} className="item-card">
                    <div className="item-header">
                      <h3>{reminder.title}</h3>
                      <button
                        onClick={() => handleDeleteReminder(reminder.id)}
                        className="delete-btn"
                      >
                        ✕
                      </button>
                    </div>
                    <p className="item-description">{reminder.description}</p>
                    <p className="item-time">🕐 {formatTime(reminder.reminder_time)}</p>
                    <p className="item-meta">
                      Notify 10 minutes before • {reminder.notified ? 'Notified ✓' : 'Pending'}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'meetings' && (
          <div className="meetings-container">
            <button onClick={handleQuickMeeting} className="action-btn">
              ➕ Schedule Meeting
            </button>

            {meetings.length === 0 ? (
              <p className="empty-state">No upcoming meetings. Schedule one to get started!</p>
            ) : (
              <div className="items-list">
                {meetings.map((meeting) => (
                  <div key={meeting.id} className="item-card">
                    <div className="item-header">
                      <h3>{meeting.title}</h3>
                    </div>
                    {meeting.description && (
                      <p className="item-description">{meeting.description}</p>
                    )}
                    <p className="item-time">📅 {formatTime(meeting.start_time)}</p>
                    {meeting.location && (
                      <p className="item-meta">📍 {meeting.location}</p>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'notifications' && (
          <div className="notifications-container">
            {notifications.length === 0 ? (
              <p className="empty-state">No notifications yet.</p>
            ) : (
              <div className="items-list">
                {notifications.map((notif) => (
                  <div
                    key={notif.id}
                    className={`notification-card ${notif.read ? 'read' : 'unread'}`}
                  >
                    <p>{notif.message}</p>
                    <p className="notification-time">
                      {new Date(notif.sent_at).toLocaleTimeString()}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
